type carveout_case = {
  individual : t; (* reuses (b)(3)(B) individual record *)
  had_pending_adjustment_of_status_application : bool; (* (b)(3)(C)(i) *)
  took_other_steps_to_apply_for_lpr_status : bool; (* (b)(3)(C)(ii) *)
}

(* (b)(3)(C) — during current year, sought adjustment of status or otherwise pursued LPR status *)
let pursued_lawful_permanent_resident_status (individual : carveout_case) : bool =
  individual.had_pending_adjustment_of_status_application ||
  individual.took_other_steps_to_apply_for_lpr_status

(* (b)(3)(C) — (b)(3)(B) closer connection exception unavailable if individual pursued LPR status this year *)
let meets_closer_connection_exception_after_carveout (individual : carveout_case) : bool =
  meets_closer_connection_exception individual.individual &&
  not (pursued_lawful_permanent_resident_status individual)
